from __future__ import annotations

import asyncio
import os
import subprocess
import sys
from pathlib import Path
from types import SimpleNamespace

import pytest
from pydantic_ai.models.test import TestModel
from ui import ai_switch, assign, inline_edit, inline_terminal
from ui import config as config_module
from ui.config import config
from ui.session import Session

APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"


def test_no_problem_with_the_setting_on_and_a_key() -> None:
    assert ai_switch.ai_problem() == ""
    ai_switch.require_ai()  # nothing raised


@pytest.mark.usefixtures("ai_off")
def test_the_setting_unticked_says_where_to_tick_it() -> None:
    assert ai_switch.ai_problem() == "allow_ai isn't ticked in /config"
    with pytest.raises(ai_switch.AiNotAllowedError, match="allow_ai isn't ticked"):
        ai_switch.require_ai()


def test_no_key_has_its_own_reason(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(ai_switch, "get_settings", lambda: SimpleNamespace(pydantic_project_api_key=None))
    assert ai_switch.ai_problem() == "no AI key is stored (run `ds settings sync`)"


def test_the_setting_is_a_checkbox_kept_out_of_the_file_while_on(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    file = tmp_path / "config.toml"
    monkeypatch.setattr(config_module, "CONFIG_FILE", file)
    assert config.allow_ai is True
    assert config.stored()["allow_ai"] is True  # what the form's checkbox starts on
    config.set_allow_ai(False)
    assert config.allow_ai is False
    assert "allow_ai = false" in file.read_text(encoding="utf-8")
    config.set_allow_ai(True)  # the default: not set, so the key leaves the file
    assert config.allow_ai is True
    assert "allow_ai" not in file.read_text(encoding="utf-8").split("\n", 3)[-1]
    file.write_text("allow_ai = false\n", encoding="utf-8")  # a hand edit applies on the next use
    assert config.allow_ai is False


@pytest.mark.usefixtures("ai_off")
def test_without_the_ai_no_inline_chat_reaches_its_model() -> None:
    # a TestModel would answer: the error shows the guard ran first, and nothing was asked
    model = TestModel()
    refused = "AiNotAllowedError: allow_ai isn't ticked in /config"
    with inline_terminal.command_agent.override(model=model):
        answer = asyncio.run(inline_terminal.ask({"instruction": "list files", "screen": "$ "}))
    assert answer["error"] == refused
    with inline_edit.edit_agent.override(model=model):
        answer = asyncio.run(inline_edit.edit({"instruction": "sort it", "before": "x = 1", "language": "python"}))
    assert answer["error"] == refused
    with assign.assign_agent.override(model=model):
        proposal = asyncio.run(assign.propose(Session(), "", "top = the best players"))
    assert proposal.error == refused
    assert model.last_model_request_parameters is None  # never called


@pytest.mark.usefixtures("ai_off")
def test_without_the_ai_from_url_in_assigned_code_is_refused() -> None:
    ran = assign.run(Session(), 'page = from_url("https://example.com", str, "the title")')
    assert ran.error == "Not assigned: from_url asks the AI, and allow_ai isn't ticked in /config"


@pytest.mark.parametrize("backend", ["keyring.backends.null.Keyring", "keyring.backends.fail.Keyring"])
def test_the_app_imports_with_no_keys(backend: str) -> None:
    # null: a keyring with nothing stored; fail: no keyring service on the machine. In a
    # process of its own, since settings and the agents are read when the modules load.
    drop = ("PYDANTIC_AI_GATEWAY_API_KEY", "STARTGG_API_TOKEN")
    env = {name: value for name, value in os.environ.items() if name not in drop}
    # the whole app, then what reads a key when the page opens: the spend meters say "setup"
    code = "; ".join(
        [
            "import ui.ui, ui.ai_switch as s",
            "from ui import spend",
            "assert spend.load(top=False).status == 'setup'",
            "print(s.ai_problem())",
        ]
    )
    done = subprocess.run(  # this interpreter, a fixed line of code
        [sys.executable, "-c", code],
        cwd=APP_DIR,
        env={**env, "PYTHON_KEYRING_BACKEND": backend},
        capture_output=True,
        text=True,
        timeout=120,
        check=False,
    )
    assert done.returncode == 0, done.stderr[-800:]
    assert done.stdout.strip()  # a reason: this machine's setting, or the missing key
